def sta_lta(x, fs=k.datapersecond, sta_seconds=2, lta_seconds=30):
    # this code generated by scienceos.ai
    '''
    Line by line
    * `x = np.asarray(x, dtype=float)` converts the input to a NumPy array of floating-point values.
    That lets the function work with lists or arrays and avoids integer arithmetic when squaring samples.
    * `sta_n = ...` and `lta_n = ...` convert the window lengths from seconds to samples. At 10 Hz, 2 seconds
    is 20 samples and 30 seconds is 300 samples. `max` prevents a window from being zero samples and ensures
    the LTA window is longer than the STA window.
    * `power = x**2` squares each sample. This makes positive and negative excursions contribute positively,
    and gives more weight to larger amplitudes. In STA/LTA terminology, the input being averaged is
    a **characteristic function**.
    * `uniform_filter1d(..., size=...)` calculates a moving average of that squared-amplitude series.
    `sta` is the short-window average; `lta` is the long-window average.
    * `ratio = ...` divides the short-term average by the long-term average. Seismic triggers commonly
    compare an STA characteristic with a threshold related to the LTA, but the choice of characteristic
    and operating parameters affects detections and false triggers. (Allen, 1982)
    * `np.maximum(lta, 1e-12)` puts a small floor under the denominator to avoid division by zero or
    an extremely small value. The value `1e-12` is just a numerical safeguard here, not a
    seismological threshold; its appropriateness depends on your data’s units and scale.
    '''
    x = np.asarray(x, dtype=float)
    sta_n = max(1, round(sta_seconds * fs))
    lta_n = max(sta_n + 1, round(lta_seconds * fs))
    power = x**2
    sta = uniform_filter1d(power, size=sta_n, mode="nearest")
    lta = uniform_filter1d(power, size=lta_n, mode="nearest")
    ratio = sta / np.maximum(lta, 1e-12)
    return sta, lta, ratio


def colour_list(size):
    returnlist = []
    # c = ['#c7a5aa', '#b19297', '#9c8185', '#877074', '#735e62', '#5e4d50', '#4a3c3f', '#352b2d', '#21191c', '#0c080a']
    c = ['#00202e', '#2c4875', '#8a508f', '#bc5090', '#ff6361', '#ff8531', '#ffa600', '#80d353', '#609f3f', '#406a2a']
    for i in range(0, size):
        j = int((i / size) * 10)
        returnlist.append(c[j])
    return returnlist


